import json, re, collections, sys

def norm(s):
    s = re.sub('[أإآ]', 'ا', s); s = s.replace('ة', 'ه').replace('ى', 'ي'); s = re.sub(r'[ًٌٍَُِّْـ]', '', s)
    s = re.sub(r'(\d)([^\d\s.,*×/])', r'\1 \2', s)
    s = re.sub(r'بدون اضافه سكر|بدون سكر مضاف|بدون سكر|زيرو سكر|خالي من السكر|قليل السكر|سكر اقل|خالي السكر', ' ', s)
    s = re.sub(r'[.\-_/*+()]', ' ', s)
    return ' ' + re.sub(r'\s+', ' ', s).strip() + ' '

PRE = r'(?<=\s)(?:و|ب|بال|ال|لل|وال|ل|فال)?'
def rx(words):
    """كلمات مفصولة بـ| ؛ الكلمة اللي تنتهي بـ! لازم تكون كلمة كاملة"""
    out = []
    for w in words.split('|'):
        w = w.strip()
        if not w: continue
        whole = w.endswith('!')
        w = w.rstrip('!').replace(' ', r'\s?')
        out.append(w + (r'(?=\s)' if whole else ''))
    return re.compile(PRE + '(?:' + '|'.join(out) + ')')

# السفر والأكواب والصحون والأكياس اللي تنستعمل مرة (١٤ نوفمبر ٢٠٢٦): كانت في «المنزل والمنوعات» وهي مستهلكات يومية،
# فصارت قسم فرعي في المنظفات (clean:disposable) جنب أكياس النفايات والمناديل. الكوب/الصحن لازم معه علامة استعمال مرة
# (ورق، بلاستيك بمقاس، اونز، الوطنية، فودي...) وبدون علامة الدائم (زجاج، ستيل، ميلامين، غضار...).
DISP = rx('سفره!|مفارش|مفرش سفره|اكياس لحم|اكياس شواء|اكياس فرن|اكياس رول حراري|اكياس حفظ|اكياس تخزين|اكياس قابله للاغلاق|اكياس بلاستيك قابله|اكياس تقفل|ورق ساندوتش|ورق سندوتش|ورق ساندويش|ورق سندويش|تغليف ساندويش|محراك|صحون قصدير|صحن قصدير|صحون رقائق|علب بلاستيك|اطباق ورقيه|صحون ورقيه')
DISP_ITEM = rx('اكواب|كاسات|كوب!|صحن|صحون|اطباق|ملاعق|شوكه|شوك!')
DISP_MARK = re.compile(r'ورق|بلاستك|بلاسكو|قصدير|رقائق|فودي|الوطنيه|اونز|اونص|اونس|انش|سفري|مقسم|\d\s?حبه|شد\s?\d{2}|بلاستيك\s(?:الحضاره|الترا|ابو\s?سهم|نماذج|صغير|ثلجي|شفاف|ملون)|ابو\s?سهم')
DISP_NOT = re.compile(r'مناديل|منديل|ملامين|ميلامين|غضار|استيل|ستيل|زجاج|قزاز|محبب|فضي|ذهبي|خشب|تيفال|معدن|سيراميك|بورسلان|السيف')

def disposable(n, before=None):
    """clean:disposable لو الاسم سفرة/أكياس حفظ، أو كوب/صحن بعلامة استعمال مرة وما قبله كلمة نوع ثانية"""
    if re.search(r'مناديل|منديل', n): return False
    if DISP.search(n): return True
    m = DISP_ITEM.search(n)
    return bool(m and (before is None or m.start() <= before) and DISP_MARK.search(n) and not DISP_NOT.search(n))

def guard(r, not_words):
    """قاعدة تتغلب بس لو ما في الاسم كلمات تنفيها (مثل «بهارات بطاطس مقلية» مو بطاطس مجمدة)"""
    no = re.compile(not_words)
    class G:
        def search(self, n): return None if no.search(n) else r.search(n)
    return G()

